    // --- 原有配色方案 ---
    { name: '薄荷蓝', accent: '#78C1C3' }, { name: '珊瑚粉', accent: '#FF7F50' },
    { name: '宁静蓝', accent: '#4682B4' }, { name: '淡雅紫', accent: '#9370DB' },
    { name: '活力橙', accent: '#FF8C00' }, { name: '清新绿', accent: '#3CB371' },
    { name: '深海蓝', accent: '#483D8B' }, { name: '金色', accent: '#FFD700' },
